def calculate_percentiles(data):
    import math
    s = sorted(data)
    n = len(s)
    def pct(k):
        i = (k / 100) * (n - 1)
        f = math.floor(i)
        c = math.ceil(i)
        if f == c:
            return s[int(i)]
        return s[f] * (c - i) + s[c] * (i - f)
    return pct(50), pct(25), pct(75)

